#pragma once

#include "mdaz/types.hpp"

namespace mdaz {

class IPlatform;
class MapGenerator;
struct MapLocation;

// Static Tilemap instances of the C2 "Map" layout (borders: water, sand, forest, base ground)
// plus runtime stamps from create_map_location (dirt tile 15 / water tile 4).
// Data: data/world_tilemaps.txt, generated by tools/extract_world_tilemaps.js.
class WorldTilemaps {
public:
  static const int kMaxMaps = 128;
#if defined(MDAZ_PSP)
  // PSP RAM: desktop uses 160k shorts (~320KB) ×2 tilemaps inside Game ≈ 640KB.
  // Slim budget keeps footprints/roads; oversized stamps are skipped in alloc_map.
  static const int kMaxTiles = 48000;
#else
  static const int kMaxTiles = 160000;
#endif

  WorldTilemaps();
  bool load(IPlatform& platform, const char* path);
  // After load, call once so clear_runtime() can drop stamped overlays only.
  void mark_static();
  void clear_runtime();
  int count() const { return count_; }

  // Fill a new local map with `tile_id` (C2 SetTile / SetTileRange equivalent).
  // world_x/y = top-left of the stamp in world pixels.
  bool stamp_fill(const char* image, float world_x, float world_y,
                  int cols, int rows, int tile_id,
                  int tile_w = 60, int tile_h = 60, int atlas_cols = 5);

  // Set one cell inside an existing stamp region; creates a 1×1 map if needed.
  bool stamp_tile(const char* image, float world_x, float world_y, int tile_id,
                  int tile_w = 60, int tile_h = 60, int atlas_cols = 5);

  // C2 create_map_location footprints + dirt corridors between nearby POIs.
  void stamp_from_mapgen(const MapGenerator& gen);
  // Single POI dirt stamp when Reload_locations calls create_map_location (tile 15).
  void stamp_location_footprint(const MapLocation& L);
  // C2 generate_location → obj518 SetTile on tilemap_forest (decoded stamp table).
  void stamp_location_forest(const MapLocation& L);
  bool ensure_ground_overlay();

  int tile_at(const char* image, float wx, float wy) const;
  // C2 tilemap_forest has the Solid behaviour: true when (wx,wy) is inside the collision
  // polygon of the forest tile under it (per-tile polys from data.js; null = full box).
  bool forest_solid_at(float wx, float wy) const;
  void draw(IPlatform& platform, const char* prefix, Vec2 cam, float scale,
            float view_w, float view_h) const;

private:
  struct Map {
    char image[40];
    float x, y;
    int cols, rows, tile_w, tile_h, atlas_cols;
    int first; // offset into tiles_
  };
  Map maps_[kMaxMaps];
  int count_;
  int static_count_;
  short tiles_[kMaxTiles];
  int tile_count_;
  int static_tile_count_;

  bool alloc_map(const char* image, float x, float y, int cols, int rows,
                 int tile_w, int tile_h, int atlas_cols, int fill_id);
};

} // namespace mdaz
